import assert from 'node:assert/strict';
import fs from 'node:fs/promises';

export async function runMotionExpandSmoke(page){
 const viewport=page.viewport(),previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()}));
 try{
  await page.evaluate(()=>{const outside=mkEl('label',{name:'Exterior',text:'Fuera de Motion Lab'});project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,elements:[outside]})];curPage=0;curSec=0;curEl=0;selection=[outside.id];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});
  const before=await page.evaluate(()=>({project:JSON.stringify(project),stored:localStorage.getItem(STORE_KEY)}));
  async function ready(text='Ideas que toman forma.'){await page.waitForFunction(text=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.querySelector('[data-motion-canvas]')&&d.querySelector('.hd')?.textContent===text;},{},text);}
  async function expand(value){await page.click('[data-motion-expand]');await page.waitForFunction(value=>{const lab=document.querySelector('.nw-motion-dialog'),f=lab.querySelector('iframe'),stage=lab.querySelector('.nw-motion-stage');return lab.classList.contains('nw-motion-expanded')===value&&Math.abs(f.contentWindow.innerWidth-f.clientWidth)<3&&stage.clientWidth>0;},{},value);}
  async function state(){return page.evaluate(()=>{const lab=document.querySelector('.nw-motion-dialog'),f=lab.querySelector('iframe'),d=f.contentDocument,n=d.querySelector('.nw-motion-selected');return {probe:d.body.dataset.expandProbe,selected:n?.dataset.id,pose:n&&['x','y','z','rx','ry','rot','scale','opacity','blur'].map(k=>n.style.getPropertyValue('--nw-sd-'+k)),moment:lab.querySelector('[data-motion-progress]').value,query:lab.querySelector('[data-motion-library-search]').value,settings:lab.querySelector('[data-motion-composition-settings]').open,scroll:lab.querySelector('.nw-motion-inspector-scroll').scrollTop,width:f.clientWidth,height:f.clientHeight};});}
  await page.click('.tb-left [data-motion-open]');await ready();await page.click('[data-motion-library-tab="elements"]');const heading=await page.$eval('[data-motion-layer]:nth-child(5)',n=>n.dataset.motionLayer);await page.click('[data-motion-layer="'+heading+'"]');await page.click('[data-motion-composition-settings]>summary');await page.click('[data-motion-library-tab="library"]');await page.click('[data-motion-library-search]');await page.keyboard.type('focus');await page.$eval('[data-motion-progress]',n=>{n.value='42';n.dispatchEvent(new Event('input',{bubbles:true}));});await page.$eval('.nw-motion-inspector-scroll',n=>n.scrollTop=180);await page.$eval('.nw-motion-dialog iframe',f=>f.contentDocument.body.dataset.expandProbe='same-document');const normal=await state();
  await expand(true);const large=await state();assert.ok(large.width>normal.width+60&&large.height>normal.height+40,'Desktop canvas grows while keeping a useful composition aspect ratio');assert.equal(large.probe,normal.probe,'Expanding keeps the same iframe document');assert.equal(large.selected,heading);assert.deepEqual(large.pose,normal.pose);assert.equal(large.moment,normal.moment);assert.equal(await page.$eval('[data-motion-expand]',n=>n.getAttribute('aria-pressed')),'true');assert.equal(await page.$eval('.nw-motion-library',n=>getComputedStyle(n).display),'none');assert.equal(await page.$eval('.nw-motion-inspector',n=>getComputedStyle(n).display),'none');
  await fs.mkdir('/tmp/nagweb-motion-visuals',{recursive:true});await (await page.$('.nw-motion-dialog')).screenshot({path:'/tmp/nagweb-motion-visuals/expanded-desktop.png'});
  await expand(false);const restored=await state();assert.deepEqual(restored,normal,'Returning preserves selection, pose, clock, search, open settings and inspector position');assert.equal(await page.$eval('[data-motion-expand]',n=>n.getAttribute('aria-pressed')),'false');
  await page.click('[data-motion-play]');const start=await page.$eval('[data-motion-progress]',n=>n.value);await expand(true);assert.equal(await page.$eval('[data-motion-play]',n=>n.getAttribute('aria-pressed')),'true');await page.waitForFunction(start=>document.querySelector('[data-motion-progress]').value!==start,{timeout:3000},start);await page.keyboard.press('Escape');assert.equal(await page.$eval('.nw-motion-dialog',n=>n.open&&!n.classList.contains('nw-motion-expanded')),true);assert.equal(await page.$eval('[data-motion-expand]',n=>n===document.activeElement),true);assert.equal(await page.$eval('[data-motion-play]',n=>n.getAttribute('aria-pressed')),'true');await page.click('[data-motion-play]');
  await expand(true);const f=await (await page.$('.nw-motion-dialog iframe')).contentFrame(),title=await f.$('[data-id="'+heading+'"]');await title.focus();await page.keyboard.press('Enter');assert.equal(await title.evaluate(n=>n.isContentEditable),true);await page.keyboard.type('Texto descartado');await page.keyboard.press('Escape');assert.equal(await title.evaluate(n=>n.textContent),'Ideas que toman forma.');assert.equal(await page.$eval('.nw-motion-dialog',n=>n.classList.contains('nw-motion-expanded')),true,'First Escape cancels inline text without collapsing the canvas');await page.keyboard.press('Escape');assert.equal(await page.$eval('.nw-motion-dialog',n=>n.open&&!n.classList.contains('nw-motion-expanded')),true,'Escape from the iframe returns to the panels');
  // Drag cancellation takes priority over leaving the expanded canvas.
  await expand(true);const box=await title.boundingBox(),x=await page.$eval('[data-motion-position="x"]',n=>n.value);await page.mouse.move(box.x+box.width/2,box.y+box.height/2);await page.mouse.down();await page.mouse.move(box.x+box.width/2+35,box.y+box.height/2+15,{steps:4});assert.notEqual(await page.$eval('[data-motion-position="x"]',n=>n.value),x);await page.keyboard.press('Escape');assert.equal(await page.$eval('[data-motion-position="x"]',n=>n.value),x);assert.equal(await page.$eval('.nw-motion-dialog',n=>n.classList.contains('nw-motion-expanded')),true);await page.mouse.up();await page.keyboard.press('Escape');assert.equal(await page.$eval('.nw-motion-dialog',n=>n.open&&!n.classList.contains('nw-motion-expanded')),true);
  assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);assert.equal(await page.evaluate(()=>localStorage.getItem(STORE_KEY)),before.stored);assert.equal(await page.evaluate(()=>history.length),0);
  // Direct editing remains available while expanded, and the result uses the usual insertion/save flow.
  await expand(true);await title.focus();await page.keyboard.press('Enter');await page.keyboard.type('Texto en el lienzo ampliado');await page.keyboard.press('Enter');await expand(false);assert.equal(await page.$eval('[data-motion-content="4"]',n=>n.value),'Texto en el lienzo ampliado');await page.click('[data-motion-insert-group]');const inserted=await page.evaluate(()=>{const g=sec().elements.find(e=>e.nwMotionInstance);return {id:g.id,project:JSON.stringify(project),text:sec().elements.find(e=>e.id===selection[0])?.text};});assert.equal(await page.evaluate(id=>sec().elements.find(e=>e.id===id).text,heading),'Texto en el lienzo ampliado');await page.evaluate(id=>NAGWEB_MOTION_LAB.edit(id),inserted.id);await ready('Texto en el lienzo ampliado');assert.equal(await page.$eval('.nw-motion-dialog',n=>n.classList.contains('nw-motion-expanded')),false);await expand(true);await page.click('[data-motion-close]');assert.equal(await page.evaluate(()=>JSON.stringify(project)),inserted.project);
  await page.setViewport({width:390,height:844,deviceScaleFactor:1});await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await ready();const compact=await state();await expand(true);assert.ok((await state()).height>compact.height+200,'Compact preview gets both panel rows');assert.ok(await page.$eval('[data-motion-expand]',n=>{const r=n.getBoundingClientRect();return r.left>=0&&r.right<=innerWidth;}));await (await page.$('.nw-motion-dialog')).screenshot({path:'/tmp/nagweb-motion-visuals/expanded-mobile.png'});await page.keyboard.press('Escape');assert.equal(await page.$eval('.nw-motion-dialog',n=>n.open&&!n.classList.contains('nw-motion-expanded')),true);await page.click('[data-motion-close]');assert.equal(await page.evaluate(()=>JSON.stringify(project)),inserted.project);
  console.log('Lienzo ampliado Motion Lab: espacio real escritorio/móvil, mismo documento/selección/pose/momento, búsqueda/desplegable/scroll conservados, reproducción continua, Escape con foco, texto y arrastre con cancelación prioritaria, edición directa e inserción habitual, reapertura/cierre sin escrituras OK');
 }catch(error){await page.screenshot({path:'/tmp/nagweb-motion-visuals/expanded-failure.png'}).catch(()=>{});throw error;
 }finally{
  await page.mouse.up();await page.setViewport(viewport);await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);
 }
}
